from dataclasses import dataclass, field

@dataclass(slots=True)
class TreeNode:
    value: int
    children: list = field(default_factory=list)

    def add_child(self, node):
        self.children.append(node)

    def __repr__(self):
        return f'TreeNode({self.value!r}, {self.children!r})'

