@dataclass
class Patient:
    id: int
    name: str

@dataclass
class InPatient(Patient):
    room_number: int

    def __post_init__(self):
        if self.room_number <= 0:
            raise ValueError('room_number must be positive')

@dataclass
class OutPatient(Patient):
    appointment_time: datetime

